/** Τα ονόματα σε μια φράση, με «και» πριν από το τελευταίο. */
const namesOf = (list: readonly Subprocessor[]): string => {
  const n = list.map(s => s.name);
  return n.length < 2 ? n.join('') : `${n.slice(0, -1).join(', ')} και ${n[n.length - 1]}`;
};

/**
 * ΤΑ ΟΡΙΑ ΑΚΙΝΗΤΩΝ ΑΠΟ ΤΑ PLANS, ΟΠΩΣ ΚΑΙ ΟΙ ΤΙΜΕΣ. Εγραφαν «έως τρία» και «έως
 * δεκαπέντε» με το χέρι δίπλα σε τιμές που διαβάζονταν από τη μηχανή. Και το
 * «απεριόριστα ακίνητα και χρήστες» έφυγε: κανένα πακέτο δεν μετρά χρήστες
 * (plans.ts), οπότε το «και χρήστες» άφηνε να εννοηθεί όριο στα άλλα.
 */
const propertiesFor = (id: keyof typeof PLANS): string => {
  const n = PLANS[id].maxProperties;
  if (!Number.isFinite(n)) return 'απεριόριστα ακίνητα';
  return n === 1 ? 'ένα ακίνητο' : `έως ${n} ακίνητα`;
};

/** Μήνες σε αιτιατική: «έναν μήνα», «2 μήνες». */
const monthsAcc = (n: number): string => (n === 1 ? 'έναν μήνα' : `${n} μήνες`);

/**
 * ΤΑ ΠΑΚΕΤΑ ΤΩΝ ΑΝΤΑΜΟΙΒΩΝ ΔΙΑΒΑΖΟΝΤΑΙ ΑΠΟ ΤΗ ΜΗΧΑΝΗ, ΟΧΙ ΑΠΟ ΤΟ ΧΕΡΙ. Οι Οροι
 * έλεγαν «ένας μήνας συνδρομής» χωρίς πακέτο και «ένα πακέτο πάνω από το δικό
 * σου», που για τον «Ιδιοκτήτη» σήμαινε δύο σκαλιά και για τον «Επαγγελματία+»
 * κανένα. Ο στόχος όγκου του ιδιώτη δίνει «owner» και ο στόχος του
 * επαγγελματία «agency» (claim_referral_bonus, migration 20260811090000)· δεν
 * υπάρχει σταθερά στον κώδικα της εφαρμογής, οπότε γράφονται εδώ, μία φορά.
 */
const REWARD_PLAN = {
  proOutcome: PLANS[individualReferrerReward(false, 'agency').tier].name,
  indivVolume: PLANS.owner.name,
  proPaid: PLANS.agency.name,
  partnerFromOwner: PLANS[partnerWelcomeTier('owner')].name,
  partnerElse: PLANS[partnerWelcomeTier('office')].name,
};

